EVENTS 
	g1: getInstance(algorithm); 
	g2: getInstance(algorithm, _); 
	Get := g1 | g2; 

	i1: init(size);
	i2: init(size, random); 
	i3: init(genParamSpec); 
	i4: init(genParamSpec, random); 
	Init := i1 | i2 | i3 | i4;

	gp1: algParams = generateParameters();
	GenParam := gp1; 
ORDER
	Get, Init, GenParam</pre>

